def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    counts = {}
    first_occurrence = {}
    original_case = {}

    for i, word in enumerate(words):
        low_word = word.lower()
        if low_word not in counts:
            counts[low_word] = 1
            first_occurrence[low_word] = i
            original_case[low_word] = word
        else:
            counts[low_word] += 1

    # 排序规则：
    # 1. 频次降序 (-counts[w])
    # 2. 第一次出现的位置升序 (first_occurrence[w])
    sorted_words = sorted(
        counts.keys(),
        key=lambda w: (-counts[w], first_occurrence[w])
    )

    result = [(original_case[w], counts[w]) for w in sorted_words[:k]]
    return result
