def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not intervals:
        return []

    # 拷贝并校验数据，不修改原列表
    valid_intervals = []
    for start, end in intervals:
        if start > end:
            raise ValueError(f"Invalid interval: [{start}, {end}], start cannot be greater than end.")
        valid_intervals.append((start, end))

    # 按起始点排序
    valid_intervals.sort()

    merged = []
    if not valid_intervals:
        return merged

    curr_start, curr_end = valid_intervals[0]

    for i in range(1, len(valid_intervals)):
        next_start, next_end = valid_intervals[i]

        # 合并条件：next_start <= current_end
        if next_start <= curr_end:
            curr_end = max(curr_end, next_end)
        else:
            merged.append((curr_start, curr_end))
            curr_start, curr_end = next_start, next_end

    merged.append((curr_start, curr_end))
    return merged

