import json
import math

def parse_jsonl_metrics(lines: list[str]) -> dict:
    service_data = {}
    invalid_count = 0

    for line in lines:
        line = line.strip()
        if not line:
            continue

        try:
            data = json.loads(line)
        except json.JSONDecodeError:
            invalid_count += 1
            continue

        service = data.get("service")
        latency = data.get("latency_ms")
        status = data.get("status")

        # 校验字段是否存在及类型
        if not isinstance(service, str):
            invalid_count += 1
            continue
        if not isinstance(latency, (int, float)) or not isinstance(status, (int, float)):
            invalid_count += 1
            continue

        if service not in service_data:
            service_data[service] = {"latencies": [], "ok_count": 0}

        service_data[service]["latencies"].append(float(latency))
        if 200 <= status < 300:
            service_data[service]["ok_count"] += 1

    result = {"invalid": invalid_count}

    for service in sorted(service_data.keys()):
        data = service_data[service]
        latencies = data["latencies"]
        n = len(latencies)

        ok_rate = data["ok_count"] / n if n > 0 else 0.0
        p95_latency = None
        if n > 0:
            latencies.sort()
            # ceil(0.95 * n) - 1
            idx = math.ceil(0.95 * n) - 1
            p95_latency = latencies[idx]

        result[service] = {
            "count": n,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95_latency
        }

    return result

