class CycleError(Exception):
    def __init__(self, cycle: list[str]):
        self.cycle = cycle
        super().__init__(f"Cycle detected: {' -> '.join(cycle)}")

def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set = set(nodes)
    adj = {n: set() for n in nodes}
    in_degree = {n: 0 for n in nodes}

    for u, v in edges:
        if u not in node_set or v not in node_set:
            raise ValueError(f"Edge contains unknown node: {u}-{v}")
        if u == v:
            raise CycleError([u, u])
        if v not in adj[u]:
            adj[u].add(v)
            in_degree[v] += 1

    import heapq
    # Kahn's algorithm with min-priority queue for lexicographical order
    queue = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) < len(nodes):
        # Find the cycle using DFS
        visited = {}
        stack = []
        path_set = {}

        def find_cycle(u):
            visited[u] = True
            stack.append(u)
            path_set[u] = len(stack) - 1
            for v in adj[u]:
                if v not in visited:
                    res = find_cycle(v)
                    if res: return res
                elif v in path_set:
                    # Extract the cycle
                    start = path_set[v]
                    return stack[start:] + [v]
            stack.pop()
            del path_set[u]
            return None

        for node in nodes:
            if node not in visited:
                cycle = find_cycle(node)
                if cycle:
                    raise CycleError(cycle)

    return result

