import collections

class StreamingGroupSum:
    def __init__(self, rows):
        self.rows = rows
        self.invalid_count = 0

    def __iter__(self):
        sums = collections.defaultdict(float)
        order = []

        for row in self.rows:
            try:
                # 验证格式是否为 3 个元素
                parts = list(row)
                if len(parts) != 3:
                    self.invalid_count += 1
                    continue

                timestamp, key, value = parts

                # 验证 value 是否为数值
                val_float = float(value)

                if key not in sums:
                    order.append(key)
                sums[key] += val_float

            except (ValueError, TypeError):
                self.invalid_count += 1
                continue

        for key in order:
            yield (key, sums[key])

def streaming_group_sum(rows):
    return StreamingGroupSum(rows)
