import time

def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    if attempts <= 0:
        raise ValueError("attempts must be greater than 0")

    last_exception = None
    for n in range(attempts):
        try:
            return fn()
        except Exception as e:
            last_exception = e
            if not retry_if(e) or n == attempts - 1:
                raise e

            # 第 n 次重试前（n从0开始），等待 base_delay * 2^n
            sleep(base_delay * (2 ** n))

    raise last_exception
