import copy

def apply_patch_ops(document: dict, operations: list) -> dict:
    """
    对嵌套字典执行事务式更新。
    """
    # 深拷贝输入，确保不修改原文档
    new_doc = copy.deepcopy(document)

    for op, path, value in operations:
        parts = path.split('.')
        current = new_doc

        # 遍历到目标节点的父节点
        for i, part in enumerate(parts[:-1]):
            if part not in current:
                current[part] = {}
            if not isinstance(current[part], dict):
                raise ValueError(f"Path component '{part}' is not a dictionary")
            current = current[part]

        last_key = parts[-1]

        if op == "set":
            current[last_key] = value

        elif op == "delete":
            if last_key in current:
                del current[last_key]

        elif op == "increment":
            if last_key not in current:
                raise KeyError(f"Path '{path}' not found for increment")
            if not isinstance(current[last_key], (int, float)):
                raise TypeError(f"Value at '{path}' is not numeric")
            if not isinstance(value, (int, float)):
                raise TypeError(f"Increment value must be numeric")
            current[last_key] += value

        else:
            raise ValueError(f"Unknown operation: {op}")

    return new_doc
