import asyncio

async def run_with_deadline(coros, limit: int, timeout: float):
    n = len(coros)
    results = [None] * n
    # 存储任务映射：{task: index}
    tasks = {}
    # 待处理的索引队列
    next_idx = 0

    async def worker(idx, coro):
        try:
            val = await coro
            results[idx] = ("ok", val)
        except asyncio.CancelledError:
            results[idx] = ("cancelled", None)
            raise
        except Exception as e:
            results[idx] = ("error", e)

    start_time = asyncio.get_event_loop().time()

    try:
        async with asyncio.timeout(timeout):
            # 初始启动任务，直到达到 limit
            while len(tasks) < limit and next_idx < n:
                t = asyncio.create_task(worker(next_idx, coros[next_idx]))
                tasks[t] = next_idx
                next_idx += 1

            while tasks:
                # 等待任意一个任务完成
                done, _ = await asyncio.wait(tasks.keys(), return_when=asyncio.FIRST_COMPLETED)
                for t in done:
                    tasks.pop(t)
                    # 如果后面还有未启动的任务，启动下一个
                    if next_idx < n:
                        new_t = asyncio.create_task(worker(next_idx, coros[next_idx]))
                        tasks[new_t] = next_idx
                        next_idx += 1

    except asyncio.TimeoutError:
        # 超时，取消所有正在运行的任务
        for t in tasks.keys():
            t.cancel()
        # 等待取消操作完成，以防止 pending 警告
        if tasks:
            await asyncio.wait(tasks.keys(), return_exceptions=True)

    # 检查那些从未被启动或未完成的任务，标记为 cancelled
    for i in range(n):
        if results[i] is None:
            results[i] = ("cancelled", None)

    return results
