import threading

class BoundedQueue:
    def __init__(self, capacity):
        self._q = []
        self._cap = capacity
        self._lock = threading.Lock()
        self._not_full = threading.Condition(self._lock)
        self._not_empty = threading.Condition(self._lock)
        self._closed = False

    def put(self, item):
        with self._lock:
            while len(self._q) >= self._cap:
                if self._closed:
                    raise RuntimeError("Queue is closed")
                self._not_full.wait()

            if self._closed:
                raise RuntimeError("Queue is closed")

            self._q.append(item)
            self._not_empty.notify()

    def get(self):
        with self._lock:
            while len(self._q) == 0:
                if self._closed:
                    raise RuntimeError("Queue is closed and empty")
                self._not_empty.wait()

            item = self._q.pop(0)
            self._not_full.notify()
            return item

    def close(self):
        with self._lock:
            if not self._closed:
                self._closed = True
                self._not_full.notify_all()
                self._not_empty.notify_all()
