import copy

class VersionedStore:
    def __init__(self):
        # Internal storage: key -> (version, value)
        self._data = {}
        self._lock = threading.RLock()

    def read(self, key):
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return None
            # Return a deep copy to prevent caller from modifying internal state
            return copy.deepcopy(entry[1])

    def compare_and_set(self, key, expected_version, value):
        with self._lock:
            entry = self._data.get(key)

            if entry is None:
                if expected_version == 0:
                    self._data[key] = (1, copy.deepcopy(value))
                    return True
                return False

            if entry[0] == expected_version:
                self._data[key] = (expected_version + 1, copy.deepcopy(value))
                return True
            return False

    def delete(self, key, expected_version):
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return False

            if entry[0] == expected_version:
                del self._data[key]
                return True
            return False

    def snapshot(self):
        with self._lock:
            # Create a deep copy of all values at this atomic moment
            # This ensures a consistent view and isolation
            return {k: copy.deepcopy(v[1]) for k, v in self._data.items()}
