import collections

class ReplicatedLog:
    def __init__(self):
        # log stores tuples of (term, command)
        self.log = [(0, None)]  # Index 0 is dummy
        self.current_term = 0
        self.commit_index = 0
        self.last_applied = 0

    def append(self, command):
        """Leader调用: 向本地添加新日志"""
        self.log.append((self.current_term, command))
        return len(self.log) - 1

    def receive_append(self, term, prev_index, prev_term, entries, leader_commit):
        """Follower调用: 处理 AppendEntries RPC
        返回 (success, conflict_index)
        """
        if term < self.current_term:
            return False, 0

        # 更新 term
        if term > self.current_term:
            self.current_term = term

        # 检查 prev_index 和 prev_term 是否匹配
        if prev_index >= len(self.log) or self.log[prev_index][0] != prev_term:
            # 找不到匹配项，返回第一个不匹配的索引作为冲突引导
            return False, len(self.log)

        # 覆盖冲突的 suffix 并追加新 entries
        idx = prev_index + 1
        for i, entry in enumerate(entries):
            curr_idx = idx + i
            if curr_idx < len(self.log):
                if self.log[curr_idx] != entry:
                    self.log = self.log[:curr_idx]
                    self.log.append(entry)
            else:
                self.log.append(entry)

        # 更新 commit_index，不能超过本地最后项索引
        if leader_commit > self.commit_index:
            self.commit_index = min(leader_commit, len(self.log) - 1)

        return True, 0

    def commit_to(self, index):
        """外部设置提交索引"""
        if index < len(self.log):
            self.commit_index = max(self.commit_index, index)

    def apply_committed(self):
        """返回按序新提交的命令"""
        applied = []
        while self.last_applied < self.commit_index:
            self.last_applied += 1
            cmd = self.log[self.last_applied][1]
            if cmd is not None:
                applied.append(cmd)
        return applied

    def current_index(self):
        return len(self.log) - 1

    def current_term(self):
        return self.current_term

# --- 5条最能暴露错误的测试用例 ---
# 1. 冲突覆盖测试：prev_index 匹配但后续 entries 与本地日志冲突，应正确截断旧日志并替换为新日志。
# 2. 幂等性测试：连续接收相同的 receive_append 请求，log 长度不应重复增加，且 apply_committed 不应重复返回。
# 3. 越界提交测试：leader_commit 远大于本地 log 长度时，commit_index 必须被限制在本地最大索引。
# 4. 回性保护测试：在 commit_index 已经增加的情况下，若收到较小的 leader_commit，本地状态和 last_applied 不应回退。
# 5. 乱序应用测试：连续多次调用 apply_committed，确保返回的命令严格按照索引递增，且不遗漏不重复。
