#!/bin/bash

# 使用 awk 处理大文件
# 逻辑：
# 1. 使用关联数组记录每个 path 的总数和 5xx 数。
# 2. 将每个 path 的 latency 存储在多维数组或字符串中。
# 3. 在 END 阶段，对每个 path 的 latency 列表进行排序并计算 p99。
# 资源开销说明：
# - 内存：O(N)，其中 N 为唯一 path 的数量。如果 path 极其多，可能耗尽大量内存。
# - 时间：O(M log M)，其中 M 为总行数，主要耗在对每个 path 的延迟排序。
awk -F'\t' '
{
    path = $4;
    status = $2;
    latency = $3;

    count[path]++;
    if (status ~ /^5/) {
        count5xx[path]++;
    }
    # 使用逗号分隔符存储延迟，方便后续拆分
    latencies[path] = (latencies[path] == "" ? latency : latencies[path] "," latency);
}
END {
    for (p in count) {
        # 将延迟字符串转为数组
        n = split(latencies[p], arr, ",");

        # 简单插入排序（升序）
        for (i = 1; i <= n; i++) {
            for (j = i + 1; j <= n; j++) {
                if (arr[i] > arr[j]) {
                    tmp = arr[i];
                    arr[i] = arr[j];
                    arr[j] = tmp;
                }
            }
        }

        # 计算 p99：索引为 ceil(n * 0.99)
        idx = int(n * 0.99);
        if (idx < 1) idx = 1;
        p99 = arr[idx];

        # 输出中间结果，供 sort 排序
        # 格式: 5xx_count total_count p99 path
        printf "%d\t%d\t%d\t%s\n", count5xx[p]+0, count[p], p99, p;
    }
}' access.log | sort -t'\t' -k1,1nr -k4,4 | awk -F'\t' 'BEGIN {print="5xx\tTotal\tP99\tPath"} {print $1"\t"$2"\t"$3"\t"$4}'
